/**
 * Urasil_light — the cycle.
 *
 * This tab does not summarise Urasil_light; it READS it, through the same
 * writers the Urasil voice itself reads. The persona line at the bottom is
 * generated by the node from the live cycle, so if the door and the voice
 * ever disagree, the disagreement is visible on this screen rather than
 * buried in a prompt.
 */

import { useState } from 'react';
import { TabFrame, useSub } from '../components/Bianca/TabFrame';
import { useDoor } from '../components/Bianca/useDoor';
import type { DoorPending } from '../components/Bianca/useDoor';
import {
  Empty,
  EngineDown,
  KeyValue,
  Pill,
  Skeleton,
  Tile,
} from '../components/Bianca/primitives';
import { getUrasil } from '../lib/sovereign-api';
import type { Urasil } from '../lib/sovereign-api';
import { tabById } from '../components/Bianca/tabs';
import type { TabId } from '../components/Bianca/tabs';
import { AgentsPage } from './AgentsPage';
import { GardenView } from '../components/Bianca/GardenView';

const DEF = tabById('urasil')!;

export function UrasilPage({ tab = 'urasil' }: { tab?: TabId }) {
  const def = tabById(tab) ?? DEF;
  const [sub, setSub] = useSub(tab, def.subs);
  const door = useDoor<Urasil>(() => getUrasil(), []);

  return (
    <TabFrame
      tab={tab}
      subs={def.subs}
      active={sub}
      onSelect={setSub}
      title="Urasil_light"
      lede="Sonne, Mond und Tag — live aus dem Zyklus gelesen, nicht behauptet. Urasil_light ist der älteste der drei und spricht in Bildern; diese Seite spricht in Zahlen, damit du beides prüfen kannst."
      aside={<Pill tone="gold">der Zyklus</Pill>}
    >
      {sub === 'cycle' && <CycleView door={door} />}
      {sub === 'levels' && <LevelsView door={door} />}
      {sub === 'gate' && <GateView door={door} />}
      {sub === 'garden' && <GardenView />}
      {sub === 'agents' && <AgentsPage />}
    </TabFrame>
  );
}

/**
 * The non-ready states, drawn once.
 *
 * Callers narrow to `ready` BEFORE rendering anything, so this never has to
 * return a payload — which is also why it is a component and not a value: a
 * function that sometimes returns data and sometimes returns markup is a
 * function React cannot use.
 */
function DoorBody({ door }: { door: DoorPending<Urasil> }) {
  if (door.kind === 'loading') return <Skeleton rows={5} />;
  if (door.kind === 'down') return <EngineDown why={door.why} />;
  if (door.kind === 'denied') return <EngineDown why="dieser Weg ist nicht freigegeben" />;
  if (door.kind === 'interrupted') return <EngineDown why="die Lesung wurde unterbrochen" />;
  return <EngineDown why={door.message} />;
}

function CycleView({ door }: { door: ReturnType<typeof useDoor<Urasil>> }) {
  if (door.kind !== 'ready') return <DoorBody door={door} />;
  const u = door.data;
  const c = u.cycle;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-2">
        <Tile label="grundmodus" value={c.grundmodus} tone="gold" />
        <Tile label="stimmung" value={c.stimmung} />
        <Tile label="fokus" value={c.fokus} />
        <Tile label="sonne" value={c.sonne} hint={`max ${c.sonne}`} />
        <Tile label="mond" value={c.mond} hint={`max ${c.mond}`} />
        <Tile label="tag" value={c.tag} hint={c.tag >= 28 ? 'voll' : `${28 - c.tag} bis voll`} />
      </div>

      {!u.cycle_available && (
        <Empty title="Der Zyklus wurde nicht gelesen">
          Die Zyklusquelle ist derzeit nicht erreichbar. Das ist ein*ehrlicher* Zustand und
          kein Grund, eine Zahl zu erfinden — die Felder oben zeigen den letzten bekannten Stand.
        </Empty>
      )}

      <div className="grid gap-4 lg:grid-cols-2">
        <section
          className="rounded-lg border p-3"
          style={{ borderColor: 'var(--s-line)', background: 'var(--s-surface-2)' }}
        >
          <h2 className="text-[13px] font-medium mb-2" style={{ color: 'var(--s-ink)' }}>
            Woher diese Werte kommen
          </h2>
          <KeyValue
            rows={[
              ['knoten', u.node],
              ['ALF root', <span key="a" className="font-mono text-[11px]">{u.source.alf_root}</span>],
              ['infinity', <span key="b" className="font-mono text-[11px]">{u.source.infinity}</span>],
              ['quelle verfügbar', u.source.available ? 'gelesen' : 'nein'],
            ]}
          />
          {!u.source.available && (
            // "not found" is only honest next to what it costs. If Ininity.txt
            // is missing, the levels and stages further down this tab are
            // REMEMBERED, not read — and a remembered table drawn in the same
            // type as a read one is a claim wearing a record's clothes. The
            // face says exactly this (ui.html:1200); a bare `nein` did not.
            <p className="mt-2 text-[12px]" style={{ color: 'var(--s-warn)' }}>
              <strong>nicht gefunden</strong> — diese Tabelle ist Erinnerung, nicht das Buch. Die
              Stufen unten stehen so, wie sie zuletzt gelesen wurden.
            </p>
          )}
        </section>

        <section
          className="rounded-lg border p-3"
          style={{ borderColor: 'var(--s-line)', background: 'var(--s-surface-2)' }}
        >
          <h2 className="text-[13px] font-medium mb-2" style={{ color: 'var(--s-ink)' }}>
            Die Stimme, die daraus spricht
          </h2>
          <p className="text-[12px] leading-relaxed" style={{ color: 'var(--s-mut)' }}>
            {u.persona.soul}
          </p>
          <p className="text-[11px] mt-2" style={{ color: 'var(--s-mut-2)' }}>
            Dieser Text wird vom Knoten aus dem oben gelesenen Zyklus erzeugt. Stimmt er nicht
            mit den Feldern oben überein, ist das ein Fehler — und wird hier sichtbar.
          </p>
          <div className="mt-3 pt-3 border-t" style={{ borderColor: 'var(--s-line)' }}>
            <div className="text-[11px] uppercase tracking-wider mb-1" style={{ color: 'var(--s-mut-2)' }}>
              im Trio
            </div>
            <div className="flex items-center gap-1.5 flex-wrap">
              {u.voices.map((name) => (
                <Pill key={name} tone={name === u.persona.name ? 'gold' : 'mut'}>
                  {name}
                </Pill>
              ))}
            </div>
            <p className="text-[11px] mt-1.5" style={{ color: 'var(--s-mut-2)' }}>
              Drei Stimmen, eine Frage. Diese eine spricht oben; die anderen beiden halten sie im{' '}
              <span style={{ color: 'var(--s-gold)' }}>Trialog</span> auf Trab — dort wird jede
              Äußerung einzeln bewertet.
            </p>
          </div>
        </section>
      </div>
    </div>
  );
}

function LevelsView({ door }: { door: ReturnType<typeof useDoor<Urasil>> }) {
  if (door.kind !== 'ready') return <DoorBody door={door} />;
  const u = door.data;
  const entries = Object.entries(u.assessments);
  const now = entries.filter(([, a]) => a.level === u.levels[0]?.level);

  return (
    <div className="space-y-4">
      <section>
        <h2 className="text-[13px] font-medium mb-2" style={{ color: 'var(--s-ink)' }}>
          Der Atem: Look → Inspect → Conclude → Code → Test → Distribute
        </h2>
        <ol className="space-y-1.5">
          {u.levels.map((l, i) => (
            <li
              key={l.level}
              className="rounded-lg border px-3 py-2 flex items-start gap-3"
              style={{ borderColor: 'var(--s-line)', background: 'var(--s-surface-2)' }}
            >
              <span
                className="w-6 h-6 shrink-0 rounded-full grid place-items-center text-[11px] font-semibold"
                style={{
                  background: 'color-mix(in srgb, var(--s-gold) 16%, transparent)',
                  color: 'var(--s-gold)',
                }}
              >
                {i + 1}
              </span>
              <div className="min-w-0">
                <div className="text-[13px] font-medium" style={{ color: 'var(--s-ink)' }}>
                  {l.name}
                </div>
                <div className="text-[12px]" style={{ color: 'var(--s-mut)' }}>
                  {l.question}
                </div>
                {l.voice && (
                  <div className="text-[11px] mt-0.5 italic" style={{ color: 'var(--s-mut-2)' }}>
                    „{l.voice}“
                  </div>
                )}
              </div>
            </li>
          ))}
        </ol>
      </section>

      <section>
        <h2 className="text-[13px] font-medium mb-2" style={{ color: 'var(--s-ink)' }}>
          Wo der Knoten heute steht
          {now.length > 0 && (
            <span className="ml-2 text-[11px]" style={{ color: 'var(--s-mut)' }}>
              — aktuell {now.map(([d]) => d).join(', ')}
            </span>
          )}
        </h2>
        {entries.length === 0 ? (
          <Empty title="Keine Bewertung liegt vor" />
        ) : (
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {entries.map(([domain, a]) => (
              <div
                key={domain}
                className="rounded-lg border p-2.5"
                style={{ borderColor: 'var(--s-line)', background: 'var(--s-surface)' }}
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="text-[12px] font-medium" style={{ color: 'var(--s-ink)' }}>
                    {domain}
                  </span>
                  <Pill tone="gold" title={`Stufe ${a.level}`}>
                    {a.level}
                  </Pill>
                </div>
                <div className="text-[11px] mt-0.5" style={{ color: 'var(--s-mut)' }}>
                  {a.name}
                </div>
                <div className="text-[11px] mt-1" style={{ color: 'var(--s-mut-2)' }}>
                  {a.note}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

function GateView({ door }: { door: ReturnType<typeof useDoor<Urasil>> }) {
  if (door.kind !== 'ready') return <DoorBody door={door} />;
  const u = door.data;
  return (
    <div className="space-y-3">
      <p className="text-[12px]" style={{ color: 'var(--s-mut)' }}>
        Fünf Stufen, fünf Fragen. Eine Stufe, die nicht beantwortet werden kann, ist nicht
        übersprungen — sie ist die Antwort.
      </p>
      <ol className="space-y-1.5">
        {u.stages.map((s, i) => (
          <li
            key={s.name}
            className="rounded-lg border p-3"
            style={{ borderColor: 'var(--s-line)', background: 'var(--s-surface-2)' }}
          >
            <div className="flex items-center gap-2">
              <Pill tone="gold">Stufe {i + 1}</Pill>
              <span className="text-[13px] font-medium" style={{ color: 'var(--s-ink)' }}>
                {s.name}
              </span>
            </div>
            <div className="text-[12px] mt-1.5" style={{ color: 'var(--s-mut)' }}>
              {s.gate_question}
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}
